head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[Radio > M > getText]<br/>컴포넌트에 선택된 아이템의 라벨값을 반환합니다.",
    "validation" : [        
        "useItemLocale 속성 값에 따라 처리된 결과값을 반환합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 조건 설정   
    let properties = {
        useLocale: true,
        useItemLocale: true,
    };

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onlabelclick", "onradioclick"]);     

    let strTarget = '';
    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    strTarget += '<xf:select1 ' + strNameSpace + ' ' + cList + ' ' + eList + ' selectedIndex="-1" appearance="full" style="width:150px;background-color:var(--ws-gray-300);">';
    strTarget += '<xf:choices>';
    strTarget += '<xf:itemset nodeset="data:dlt_radioItem">';
    strTarget += '<xf:label ref="label"></xf:label>';
    strTarget += '<xf:value ref="value"></xf:value>';
    strTarget += '</xf:itemset>';
    strTarget += '</xf:choices>';
    strTarget += '</xf:select1>';

    // target 생성
    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "radio",
        strTarget,
        grp_comp
    ); 

    // $c.gcm.createBasicRadio(cList, eList);
}



scwin.btn_getText_onclick = function (e) {     
    let rtn = '';

	rtn = target1.getText();
    wf_body_bottom.getObj("scwin").setReturnValue("return : " + rtn);
};
